/* Function: CodeGen::emit_value_constructors */
SigilValue sigil_CodeGen____emit_value_constructors(SigilValue* self) {
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_unit(void) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_UNIT, .evidence = SIGIL_KNOWN };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_bool(bool b) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_BOOL, .evidence = SIGIL_KNOWN, .v.b = b };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_int(int64_t i) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_INT, .evidence = SIGIL_KNOWN, .v.i = i };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_float(double f) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_FLOAT, .evidence = SIGIL_KNOWN, .v.f = f };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_char(char c) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_CHAR, .evidence = SIGIL_KNOWN, .v.c = c };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_string(const char* s) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("char* copy = strdup(s);"));
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = copy };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_null(void) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_NULL, .evidence = SIGIL_UNCERTAIN };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_array(size_t len) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("/* Use header format for shared length tracking */"));
    sigil_CodeGen____line(self, sigil_string("size_t cap = len < 4 ? 4 : len;"));
    sigil_CodeGen____line(self, sigil_string("SigilArrayHeader* header = (SigilArrayHeader*)calloc(1, sizeof(SigilArrayHeader) + cap * sizeof(SigilValue));"));
    sigil_CodeGen____line(self, sigil_string("header->len = len;"));
    sigil_CodeGen____line(self, sigil_string("header->cap = cap;"));
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_ARRAY, .evidence = SIGIL_KNOWN, .v.arr = { (SigilValue*)sigil_array_data(header), len, cap } };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_with_evidence(SigilValue v, uint8_t ev) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("v.evidence = ev;"));
    sigil_CodeGen____line(self, sigil_string("return v;"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline bool sigil_truthy(SigilValue v) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("switch (v.tag) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("case TAG_BOOL: return v.v.b;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_INT: return v.v.i != 0;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_FLOAT: return v.v.f != 0.0;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_STRING: return v.v.s && v.v.s[0];"));
    sigil_CodeGen____line(self, sigil_string("case TAG_ARRAY: return v.v.arr.len > 0;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_NULL: return false;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_UNIT: return false;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_ENUM: return true;  /* Enum values are always truthy */"));
    sigil_CodeGen____line(self, sigil_string("default: return true;"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline bool sigil_eq(SigilValue a, SigilValue b) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("/* Dereference refs before comparing */"));
    sigil_CodeGen____line(self, sigil_string("if (a.tag == TAG_REF && a.v.ptr) a = *(SigilValue*)a.v.ptr;"));
    sigil_CodeGen____line(self, sigil_string("if (b.tag == TAG_REF && b.v.ptr) b = *(SigilValue*)b.v.ptr;"));
    sigil_CodeGen____line(self, sigil_string("if (a.tag != b.tag) return false;"));
    sigil_CodeGen____line(self, sigil_string("switch (a.tag) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("case TAG_BOOL: return a.v.b == b.v.b;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_INT: return a.v.i == b.v.i;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_FLOAT: return a.v.f == b.v.f;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_CHAR: return a.v.c == b.v.c;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_STRING: return strcmp(a.v.s, b.v.s) == 0;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_NULL: return true;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_UNIT: return true;"));
    sigil_CodeGen____line(self, sigil_string("case TAG_ENUM: return a.v.e.enum_id == b.v.e.enum_id && a.v.e.variant == b.v.e.variant;"));
    sigil_CodeGen____line(self, sigil_string("default: return false;"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("/* Result type helpers */"));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_Ok(SigilValue v) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("SigilValue* inner = (SigilValue*)malloc(sizeof(SigilValue));"));
    sigil_CodeGen____line(self, sigil_string("*inner = v;"));
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_RESULT_OK, .evidence = SIGIL_KNOWN, .v.ptr = inner };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_Err(SigilValue v) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("SigilValue* inner = (SigilValue*)malloc(sizeof(SigilValue));"));
    sigil_CodeGen____line(self, sigil_string("*inner = v;"));
    sigil_CodeGen____line(self, sigil_string("return (SigilValue){ .tag = TAG_RESULT_ERR, .evidence = SIGIL_KNOWN, .v.ptr = inner };"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline bool sigil_is_ok(SigilValue v) { return v.tag == TAG_RESULT_OK; }"));
    sigil_CodeGen____line(self, sigil_string("static inline bool sigil_is_err(SigilValue v) { return v.tag == TAG_RESULT_ERR; }"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static inline SigilValue sigil_char____from_u32(SigilValue codepoint) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("return sigil_char((char)(codepoint.v.i & 0xFF));"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string(""));
    sigil_CodeGen____line(self, sigil_string("static long long global_tick = 0;"));
    sigil_CodeGen____line(self, sigil_string("static inline void tick(const char* fn) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("global_tick++;"));
    sigil_CodeGen____line(self, sigil_string("if (global_tick > 100000000) { fprintf(stderr, \"Infinite loop in %s\\n\", fn); exit(1); }"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    return sigil_CodeGen____line(self, sigil_string(""));
}

