    sigil_CodeGen____line(self, sigil_string("char* out = buf;"));
    sigil_CodeGen____line(self, sigil_string("size_t remaining = sizeof(buf);"));
    sigil_CodeGen____line(self, sigil_string("const char* p = fmt;"));
    sigil_CodeGen____line(self, sigil_string("while (*p && remaining > 1) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("if (*p == \'{\' && *(p+1) == \'}\') {"));
