    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string("p += 2;"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("} else if (*p == \'{\' && *(p+1) == \':\') {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("// Skip format specifiers like {:?}"));
    sigil_CodeGen____line(self, sigil_string("while (*p && *p != \'}\') p++;"));
    sigil_CodeGen____line(self, sigil_string("if (*p == \'}\') p++;"));
    sigil_CodeGen____line(self, sigil_string("SigilValue v = va_arg(args, SigilValue);"));
    sigil_CodeGen____line(self, sigil_string("SigilValue s = sigil_display(v);"));
    sigil_CodeGen____line(self, sigil_string("if (s.tag == TAG_STRING && s.v.s) {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("size_t len = strlen(s.v.s);"));
    sigil_CodeGen____line(self, sigil_string("if (len >= remaining) len = remaining - 1;"));
    sigil_CodeGen____line(self, sigil_string("memcpy(out, s.v.s, len);"));
    sigil_CodeGen____line(self, sigil_string("out += len; remaining -= len;"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("} else if (*p == \'{\' && *(p+1) == \'{\') {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("/* {{ -> { (literal brace) */"));
    sigil_CodeGen____line(self, sigil_string("*out++ = \'{\';"));
    sigil_CodeGen____line(self, sigil_string("p += 2;"));
    sigil_CodeGen____line(self, sigil_string("remaining--;"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("} else if (*p == \'}\' && *(p+1) == \'}\') {"));
    sigil_CodeGen____indent_push(self);
    sigil_CodeGen____line(self, sigil_string("/* }} -> } (literal brace) */"));
