    sigil_CodeGen____line(self, sigil_string("if (i > 0) total += sep_len;"));
    sigil_CodeGen____indent_pop(self);
    sigil_CodeGen____line(self, sigil_string("}"));
    sigil_CodeGen____line(self, sigil_string("char* result = (char*)malloc(total + 1);"));
