static inline SigilValue sigil_enumerate(SigilValue v) {
    if (v.tag != TAG_ARRAY) return sigil_array(0);
    SigilValue result = sigil_array(v.v.arr.len);
    for (size_t i = 0; i < v.v.arr.len; i++) {
        SigilValue* fields = (SigilValue*)malloc(2 * sizeof(SigilValue));
        fields[0] = sigil_int((long long)i);
        fields[1] = v.v.arr.data[i];
        result.v.arr.data[i] = (SigilValue){ .tag = TAG_TUPLE, .evidence = SIGIL_KNOWN, .v.tup = { .fields = fields, .count = 2 } };
    }
    return result;
}
/* sigil_filter - keep elements matching predicate */
SigilValue sigil_filter(SigilValue v, SigilValue pred) {
    if (v.tag != TAG_ARRAY || !v.v.arr.data) return sigil_array(0);
    SigilValue result = sigil_array(0);
    result.v.arr.data = (SigilValue*)malloc(v.v.arr.len * sizeof(SigilValue));
    result.v.arr.cap = v.v.arr.len;
    result.v.arr.len = 0;
    SigilValue (*fn)(SigilValue) = (SigilValue (*)(SigilValue))pred.v.ptr;
    for (size_t i = 0; i < v.v.arr.len; i++) {
        SigilValue item = v.v.arr.data[i];
        SigilValue keep = fn(item);
        if (sigil_truthy(keep)) {
            result.v.arr.data[result.v.arr.len++] = item;
        }
    }
    return result;
}
/* sigil_flat_map - map and flatten results */
SigilValue sigil_flat_map(SigilValue v, SigilValue mapper) {
    if (v.tag != TAG_ARRAY || !v.v.arr.data) return sigil_array(0);
    /* First pass: count total elements */
    size_t total = 0;
    SigilValue (*fn)(SigilValue) = (SigilValue (*)(SigilValue))mapper.v.ptr;
    for (size_t i = 0; i < v.v.arr.len; i++) {
        SigilValue mapped = fn(v.v.arr.data[i]);
        if (mapped.tag == TAG_ARRAY) total += mapped.v.arr.len;
        else total += 1;
    }
    /* Second pass: collect elements */
    SigilValue result = sigil_array(total);
    size_t idx = 0;
    for (size_t i = 0; i < v.v.arr.len; i++) {
        SigilValue mapped = fn(v.v.arr.data[i]);
        if (mapped.tag == TAG_ARRAY) {
            for (size_t j = 0; j < mapped.v.arr.len; j++) {
                result.v.arr.data[idx++] = mapped.v.arr.data[j];
            }
        } else {
            result.v.arr.data[idx++] = mapped;
        }
    }
    return result;
}
#endif /* SIGIL_ITER_DEFINED */

#ifndef SIGIL_ENTRY_API_DEFINED
#define SIGIL_ENTRY_API_DEFINED
/* sigil_map_entry_or_default - get or insert default for key */
SigilValue sigil_map_entry_or_default(SigilValue map, SigilValue key) {
    /* Check if key exists */
    SigilValue existing = sigil_Map____get(map, key);
    if (existing.tag != TAG_NULL) {
        return existing;
    }
    /* Insert default value (empty array for most common case) */
    SigilValue def = sigil_array(0);
    sigil_Map____insert(map, key, def);
    return sigil_Map____get(map, key);
}
/* sigil_map_entry_or_insert - get or insert specific value for key */
SigilValue sigil_map_entry_or_insert(SigilValue map, SigilValue key, SigilValue value) {
    SigilValue existing = sigil_Map____get(map, key);
    if (existing.tag != TAG_NULL) {
        return existing;
    }
    sigil_Map____insert(map, key, value);
    return sigil_Map____get(map, key);
}
/* sigil_map_entry_or_insert_with - get or insert closure result for key */
SigilValue sigil_map_entry_or_insert_with(SigilValue map, SigilValue key, SigilValue closure) {
    SigilValue existing = sigil_Map____get(map, key);
    if (existing.tag != TAG_NULL) {
        return existing;
    }
    /* Call closure to get default value */
    SigilValue (*fn)(void) = (SigilValue (*)(void))closure.v.ptr;
    SigilValue value = fn ? fn() : sigil_unit();
    sigil_Map____insert(map, key, value);
    return sigil_Map____get(map, key);
}
#endif /* SIGIL_ENTRY_API_DEFINED */

#ifndef SIGIL_JOIN_DEFINED
#define SIGIL_JOIN_DEFINED
#include <stdint.h>
static inline int sigil_join_valid_ptr(const char* p) {
    if (!p) return 0;
    uintptr_t addr = (uintptr_t)p;
    if (addr < 0x10000) return 0;  /* Low address = likely corrupted */
    if (addr > 0x7FFFFFFFFFFF) return 0;  /* Beyond user space */
    return 1;
}
SigilValue sigil_join(SigilValue arr, SigilValue sep) {
    if (arr.tag != TAG_ARRAY || !arr.v.arr.data) return sigil_string("");
    size_t arr_len = sigil_arr_len(arr);
    if (arr_len == 0) return sigil_string("");
    if (arr_len > 100000) return sigil_string("");  /* Sanity check */
    size_t total = 0;
    const char* sep_str = (sep.tag == TAG_STRING && sigil_join_valid_ptr(sep.v.s)) ? sep.v.s : "";
    size_t sep_len = strlen(sep_str);
    for (size_t i = 0; i < arr_len; i++) {
        SigilValue item = arr.v.arr.data[i];
        if (item.tag == TAG_STRING && sigil_join_valid_ptr(item.v.s)) total += strlen(item.v.s);
        if (i > 0) total += sep_len;
    }
    char* result = (char*)malloc(total + 1);
    if (!result) return sigil_string("");
    result[0] = '\0';
    for (size_t i = 0; i < arr_len; i++) {
        if (i > 0) strcat(result, sep_str);
        SigilValue item = arr.v.arr.data[i];
        if (item.tag == TAG_STRING && sigil_join_valid_ptr(item.v.s)) strcat(result, item.v.s);
    }
    return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = result };
}
#endif /* SIGIL_JOIN_DEFINED */

SigilValue sigil_abs(SigilValue v) {
    if (v.tag == TAG_INT) return sigil_int(v.v.i < 0 ? -v.v.i : v.v.i);
    return sigil_float(fabs(v.v.f));
}

SigilValue sigil_sqrt(SigilValue v) {
    double x = v.tag == TAG_INT ? (double)v.v.i : v.v.f;
    return sigil_float(sqrt(x));
}

SigilValue sigil_sin(SigilValue v) {
    double x = v.tag == TAG_INT ? (double)v.v.i : v.v.f;
    return sigil_float(sin(x));
}

SigilValue sigil_cos(SigilValue v) {
    double x = v.tag == TAG_INT ? (double)v.v.i : v.v.f;
    return sigil_float(cos(x));
}

SigilValue sigil_pow(SigilValue base, SigilValue exp) {
    double b = base.tag == TAG_INT ? (double)base.v.i : base.v.f;
    double e = exp.tag == TAG_INT ? (double)exp.v.i : exp.v.f;
    return sigil_float(pow(b, e));
}

SigilValue sigil_assert(SigilValue cond, SigilValue msg) {
    if (!sigil_truthy(cond)) {
        fprintf(stderr, "Assertion failed: %s\n", msg.tag == TAG_STRING ? msg.v.s : "<no message>");
        exit(1);
    }
    return sigil_unit();
}

SigilValue sigil_assert_eq(SigilValue a, SigilValue b) {
    if (!sigil_eq(a, b)) {
        fprintf(stderr, "Assertion failed: values not equal\n");
        exit(1);
    }
    return sigil_unit();
}

SigilValue sigil_panic(SigilValue msg) {
    fprintf(stderr, "panic: %s\n", msg.tag == TAG_STRING ? msg.v.s : "<no message>");
    exit(1);
    return sigil_unit(); /* unreachable */
}

SigilValue sigil_concat(SigilValue a, SigilValue b) {
    if (a.tag == TAG_STRING && b.tag == TAG_STRING) {
        size_t len = strlen(a.v.s) + strlen(b.v.s) + 1;
        char* s = (char*)malloc(len);
        strcpy(s, a.v.s);
        strcat(s, b.v.s);
        return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = s };
    }
    return sigil_null();
}

SigilValue sigil_add(SigilValue a, SigilValue b) {
    if (a.tag == TAG_INT && b.tag == TAG_INT) return sigil_int(a.v.i + b.v.i);
    if (a.tag == TAG_STRING || b.tag == TAG_STRING) return sigil_concat(a, b);
    return sigil_float((a.tag == TAG_INT ? (double)a.v.i : a.v.f) + (b.tag == TAG_INT ? (double)b.v.i : b.v.f));
}

SigilValue sigil_struct(const char* name, const char** names, SigilValue* values, size_t n) {
    SigilStruct* s = (SigilStruct*)malloc(sizeof(SigilStruct));
    s->name = name;
    s->field_names = names;
    s->field_values = (SigilValue*)malloc(n * sizeof(SigilValue));
    for (size_t i = 0; i < n; i++) s->field_values[i] = values[i];
    s->num_fields = n;
    return (SigilValue){ .tag = TAG_STRUCT, .evidence = SIGIL_KNOWN, .v.ptr = s };
}

SigilValue sigil_struct_field(SigilValue v, const char* field) {
    if (v.tag != TAG_STRUCT) return sigil_null();
    SigilStruct* s = (SigilStruct*)v.v.ptr;
    for (size_t i = 0; i < s->num_fields; i++) {
        if (strcmp(s->field_names[i], field) == 0) return s->field_values[i];
    }
    return sigil_null();
}

SigilValue sigil_struct_set_field(SigilValue* v, const char* field, SigilValue val) {
    if (v->tag != TAG_STRUCT) return sigil_unit();
    SigilStruct* s = (SigilStruct*)v->v.ptr;
    for (size_t i = 0; i < s->num_fields; i++) {
        if (strcmp(s->field_names[i], field) == 0) { s->field_values[i] = val; return sigil_unit(); }
    }
    return sigil_unit();
}

int sigil_is_struct_variant(SigilValue v, const char* name) {
    /* Dereference TAG_REF if needed */
    while (v.tag == TAG_REF && v.v.ptr) {
        v = *((SigilValue*)v.v.ptr);
    }
    if (v.tag != TAG_STRUCT) return 0;
    SigilStruct* s = (SigilStruct*)v.v.ptr;
    return s && s->name && strcmp(s->name, name) == 0;
}

int sigil_is_enum_variant(SigilValue v, const char* name) {
    /* Dereference TAG_REF if needed */
    while (v.tag == TAG_REF && v.v.ptr) {
        v = *((SigilValue*)v.v.ptr);
    }
    /* Try TAG_STRUCT representation first (native compiler style) */
    if (v.tag == TAG_STRUCT) {
        SigilStruct* s = (SigilStruct*)v.v.ptr;
        return s && s->name && strcmp(s->name, name) == 0;
    }
    /* TAG_ENUM: check variant name suffix matches */
    if (v.tag == TAG_ENUM) {
        /* For enums, we can only do a best-effort match on variant name */
        /* The name format is 'EnumName::VariantName' */
        return 1; /* TODO: proper enum variant matching */
    }
    return 0;
}

int sigil_enum_eq(SigilValue a, SigilValue b) {
    /* Dereference TAG_REF if needed */
    while (a.tag == TAG_REF && a.v.ptr) a = *((SigilValue*)a.v.ptr);
    while (b.tag == TAG_REF && b.v.ptr) b = *((SigilValue*)b.v.ptr);
    /* Both must be TAG_ENUM */
    if (a.tag != TAG_ENUM || b.tag != TAG_ENUM) return 0;
    /* Compare enum_id and variant */
    return a.v.e.enum_id == b.v.e.enum_id && a.v.e.variant == b.v.e.variant;
}

SigilValue sigil_tuple(SigilValue* fields, size_t n) {
    SigilValue* data = (SigilValue*)malloc(n * sizeof(SigilValue));
    for (size_t i = 0; i < n; i++) data[i] = fields[i];
    SigilValue v = { .tag = TAG_TUPLE, .evidence = SIGIL_KNOWN };
    v.v.tup.fields = data;
    v.v.tup.count = n;
    return v;
}

/* Option helpers */
const SigilValue Option____None = { .tag = TAG_NULL, .evidence = SIGIL_KNOWN };

SigilValue sigil_Option____Some(SigilValue v) {
    SigilValue* inner = (SigilValue*)malloc(sizeof(SigilValue));
    *inner = v;
    return (SigilValue){ .tag = TAG_OPTION_SOME, .evidence = SIGIL_KNOWN, .v.ptr = inner };
}

SigilValue sigil_is_some(SigilValue v) {
    return sigil_bool(v.tag == TAG_OPTION_SOME);
}

SigilValue sigil_is_none(SigilValue v) {
    return sigil_bool(v.tag == TAG_NULL || v.tag == TAG_OPTION_NONE);
}

SigilValue sigil_String____to_uppercase(SigilValue s) {
    if (s.tag != TAG_STRING || !s.v.s) return sigil_string("");
    size_t len = strlen(s.v.s);
    char* result = (char*)malloc(len + 1);
    for (size_t i = 0; i < len; i++) {
        result[i] = (s.v.s[i] >= 'a' && s.v.s[i] <= 'z') ? s.v.s[i] - 32 : s.v.s[i];
    }
    result[len] = '\0';
    return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = result };
}

SigilValue sigil_String____to_lowercase(SigilValue s) {
    if (s.tag != TAG_STRING || !s.v.s) return sigil_string("");
    size_t len = strlen(s.v.s);
    char* result = (char*)malloc(len + 1);
    for (size_t i = 0; i < len; i++) {
        result[i] = (s.v.s[i] >= 'A' && s.v.s[i] <= 'Z') ? s.v.s[i] + 32 : s.v.s[i];
    }
    result[len] = '\0';
    return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = result };
}

/* I/O functions */
SigilValue sigil_println(SigilValue v) {
    SigilValue s = sigil_display(v);
    if (s.tag == TAG_STRING && s.v.s) { printf("%s\n", s.v.s); }
    else { printf("<value>\n"); }
    return sigil_unit();
}

SigilValue sigil_print(SigilValue v) {
    SigilValue s = sigil_display(v);
    if (s.tag == TAG_STRING && s.v.s) { printf("%s", s.v.s); }
    return sigil_unit();
}

SigilValue sigil_eprintln(SigilValue v) {
    SigilValue s = sigil_display(v);
    if (s.tag == TAG_STRING && s.v.s) { fprintf(stderr, "%s\n", s.v.s); }
    return sigil_unit();
}

/* File I/O functions for FFI */
static size_t __sigil_last_file_len = 0;

SigilValue sigil_read_file(SigilValue path, SigilValue len) {
    if (path.tag != TAG_STRING || !path.v.s) return sigil_null();
    FILE* f = fopen(path.v.s, "rb");
    if (!f) return sigil_null();
    fseek(f, 0, SEEK_END);
    size_t size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* buf = (char*)malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);
    __sigil_last_file_len = size;
    return sigil_string(buf);
}

SigilValue sigil_file_len(void) {
    return sigil_int(__sigil_last_file_len);
}

SigilValue sigil_write_file(SigilValue path, SigilValue path_len, SigilValue content, SigilValue content_len) {
    (void)path_len; (void)content_len; /* length params unused - null-terminated */
    if (path.tag != TAG_STRING || !path.v.s) return sigil_bool(false);
    if (content.tag != TAG_STRING || !content.v.s) return sigil_bool(false);
    FILE* f = fopen(path.v.s, "w");
    if (!f) return sigil_bool(false);
    fputs(content.v.s, f);
    fclose(f);
    return sigil_bool(true);
}

SigilValue sigil_String____from_raw_parts(SigilValue ptr, SigilValue len, SigilValue cap) {
    (void)cap; /* capacity unused */
    if (ptr.tag != TAG_STRING) return sigil_string("");
    /* ptr already contains the string from sigil_read_file */
    return ptr;
}

SigilValue sigil_with_span(SigilValue err, SigilValue span) {
    /* Add span info to error - for now just return unchanged */
    (void)span;
    return err;
}

SigilValue sigil_as_ptr(SigilValue s) {
    /* Return the string pointer wrapped as a SigilValue - used for FFI */
    if (s.tag == TAG_STRING) return s;
    return sigil_null();
}

SigilValue sigil_is_null(SigilValue v) {
    return sigil_bool(v.tag == TAG_NULL);
}

